import hashlib
import itertools
import json
import math
import platform
import time
from collections.abc import Mapping
from importlib.metadata import PackageNotFoundError, version
from numbers import Integral

import networkx as nx
import numpy as np
from scipy.optimize import minimize
from qiskit import QuantumCircuit, transpile
from qiskit.circuit import ParameterVector
from qiskit_aer import AerSimulator


CITY_COORDINATES_KM = {
    "C0": (0, 0), "C1": (3, 0), "C2": (6, 0),
    "C3": (0, 3), "C4": (3, 3), "C5": (6, 3),
    "C6": (0, 6), "C7": (3, 6), "C8": (6, 6),
}

PROVIDED_ROAD_EDGES = [
    ("C0", "C1"), ("C1", "C2"),
    ("C3", "C4"), ("C4", "C5"),
    ("C6", "C7"), ("C7", "C8"),
    ("C0", "C3"), ("C3", "C6"),
    ("C1", "C4"), ("C4", "C7"),
    ("C2", "C5"), ("C5", "C8"),
]


def build_road_network(vertices, coordinates_km, radius_km=3.5):
    """Evaluate every unordered pair; an edge exists iff distance <= radius."""
    vertices = list(vertices)
    radius_km = float(radius_km)
    if not math.isfinite(radius_km) or radius_km < 0:
        raise ValueError("radius_km must be finite and nonnegative.")
    if len(set(vertices)) != len(vertices):
        raise ValueError("Vertex labels must be unique.")

    coordinates = {}
    for vertex in vertices:
        point = np.asarray(coordinates_km[vertex], dtype=float)
        if point.shape != (2,) or not np.all(np.isfinite(point)):
            raise ValueError("Each city must have two finite coordinates.")
        coordinates[vertex] = point

    edges, distances = [], []
    for u, v in itertools.combinations(vertices, 2):
        distance = float(np.linalg.norm(coordinates[u] - coordinates[v]))
        connected = distance <= radius_km
        distances.append({
            "cities": [u, v],
            "distance_km": distance,
            "connected": connected,
        })
        if connected:
            edges.append((u, v))

    return edges, {
        "coordinates_km": {
            vertex: coordinates[vertex].tolist() for vertex in vertices
        },
        "connection_radius_km": radius_km,
        "evaluated_pair_count": len(distances),
        "edge_count": len(edges),
        "pairwise_distances": distances,
    }


def _positive_integer(name, value):
    if isinstance(value, bool) or not isinstance(value, Integral) or value < 1:
        raise ValueError(f"{name} must be a positive integer.")
    return int(value)


def _canonical_mask(mask, full_mask):
    # Qiskit qubit i represents vertices[i]. Fix vertex 0 in region A,
    # identifying complementary assignments as the same bipartition.
    return full_mask ^ mask if mask & 1 else mask


def _reference_mask(reference, vertices):
    """
    Accept None, two groups, a region->vertices mapping, a vertex->region
    mapping, or a binary assignment vector in vertex order.
    """
    if reference is None:
        return None

    vertex_set = set(vertices)
    if isinstance(reference, Mapping):
        if set(reference) == vertex_set:
            labels = [reference[v] for v in vertices]
            if len(set(labels)) != 2:
                raise ValueError("The reference must use exactly two regions.")
            first_label = labels[0]
            groups = [
                [v for v in vertices if reference[v] == first_label],
                [v for v in vertices if reference[v] != first_label],
            ]
        elif len(reference) == 2:
            groups = list(reference.values())
        else:
            raise ValueError("Unrecognized reference partition mapping.")
    else:
        values = list(reference)
        is_binary_vector = (
            len(values) == len(vertices)
            and all(isinstance(x, Integral) and x in (0, 1) for x in values)
        )
        if is_binary_vector:
            groups = [
                [v for v, bit in zip(vertices, values) if bit == 0],
                [v for v, bit in zip(vertices, values) if bit == 1],
            ]
        elif len(values) == 2:
            groups = values
        else:
            raise ValueError("Reference must contain two groups or n binary labels.")

    groups = [list(group) for group in groups]
    a, b = map(set, groups)
    if (
        not a or not b or a & b or a | b != vertex_set
        or len(a) != len(groups[0]) or len(b) != len(groups[1])
    ):
        raise ValueError("Reference groups must partition every vertex exactly once.")

    mask = sum(1 << i for i, v in enumerate(vertices) if v in b)
    return _canonical_mask(mask, (1 << len(vertices)) - 1)


def _candidate_key(record):
    # The declared weighted objective is primary. Resolve exact objective
    # ties using modularity, normalized cut, balance, then a canonical label.
    return (
        record["weighted_objective"],
        -record["modularity_score"],
        record["normalized_cut_score"],
        record["size_imbalance"],
        record["canonical_mask"],
    )


def _minimization_ratio(value, optimum):
    """Standard minimization ratio: obtained / optimum; one is optimal."""
    if optimum == 0:
        return 1.0 if value == 0 else math.inf
    return float(value / optimum)


def _local_refine(mask, candidates, n):
    """Deterministic descent over single-city moves and two-city swaps."""
    full_mask = (1 << n) - 1
    start = mask
    accepted_moves = 0
    while True:
        neighbors = {mask}
        for i in range(n):
            moved = mask ^ (1 << i)
            if moved not in (0, full_mask):
                neighbors.add(_canonical_mask(moved, full_mask))
        for i, j in itertools.combinations(range(n), 2):
            if ((mask >> i) & 1) != ((mask >> j) & 1):
                swapped = mask ^ (1 << i) ^ (1 << j)
                neighbors.add(_canonical_mask(swapped, full_mask))
        best = min(neighbors, key=lambda x: _candidate_key(candidates[x]))
        if _candidate_key(candidates[best]) >= _candidate_key(candidates[mask]):
            break
        mask = best
        accepted_moves += 1
    return mask, {
        "starting_mask": start,
        "accepted_moves": accepted_moves,
        "method": "single-city moves and opposite-region city swaps",
    }


def _package_versions():
    result = {"python": platform.python_version()}
    for package in ("qiskit", "qiskit-aer", "numpy", "scipy", "networkx"):
        try:
            result[package] = version(package)
        except PackageNotFoundError:
            result[package] = "unknown"
    return result


def solve_graph_partition_qaoa(
    graph_vertices,
    graph_edges,
    known_reference_partition,
    p_layers=2,
    lambda_balance=0.4,
    lambda_cut=3.0,
    opt_shots=1024,
    final_shots=4096,
    maxiter=80,
    n_repro_runs=3,
    seed=42,
):
    """
    Shot-based QAOA followed by deterministic local refinement.

    Minimize, over two NONEMPTY regions,
        E(x) = lambda_cut * cut(x)
               + lambda_balance * (|A| - |B|)^2.

    Balance is a soft penalty, not an exact-cardinality constraint. With the
    supplied defaults, a 4/5 split with four crossing roads costs 12.4,
    whereas a straight 3/6 split with three crossing roads costs 12.6.
    Thus fewer crossing roads alone is NOT the complete optimization target.

    All 2^(n-1)-1 nonempty, unlabeled bipartitions are evaluated classically
    for diagnostics and an exact benchmark. The returned partition is chosen
    from QAOA observations plus local refinement, not replaced by the exact
    enumerated optimum. No quantum speedup is claimed.

    The exact benchmark limits this implementation to at most 16 vertices.
    For the task's nine named cities, edges are reconstructed from coordinates
    and checked against graph_edges by evaluating all 36 pairwise distances.

    Metric conventions:
      modularity = standard unweighted two-community modularity;
      normalized_cut = cut/vol(A) + cut/vol(B), lower is better;
      balance_constraint_score = 1 - abs(|A|-|B|)/n, higher is better;
      approximation_ratio = returned weighted objective / exact optimum.

    For n=9, the maximum balance score is 8/9, not 1. For an edgeless
    graph modularity is defined as zero; a zero-volume, zero-cut normalized
    cut contribution is defined as zero.
    """
    started = time.perf_counter()
    vertices = list(graph_vertices)
    n = len(vertices)
    if not 2 <= n <= 16 or len(set(vertices)) != n:
        raise ValueError("Provide 2 to 16 distinct vertex labels.")
    p_layers = _positive_integer("p_layers", p_layers)
    opt_shots = _positive_integer("opt_shots", opt_shots)
    final_shots = _positive_integer("final_shots", final_shots)
    maxiter = _positive_integer("maxiter", maxiter)
    n_repro_runs = _positive_integer("n_repro_runs", n_repro_runs)
    if isinstance(seed, bool) or not isinstance(seed, Integral) or seed < 0:
        raise ValueError("seed must be a nonnegative integer.")
    seed = int(seed)
    lambda_balance, lambda_cut = float(lambda_balance), float(lambda_cut)
    if (
        not math.isfinite(lambda_balance) or not math.isfinite(lambda_cut)
        or lambda_balance < 0 or lambda_cut < 0
        or lambda_balance + lambda_cut == 0
    ):
        raise ValueError("Objective weights must be finite, nonnegative, and not both zero.")

    index = {v: i for i, v in enumerate(vertices)}
    supplied_edges = []
    for edge in graph_edges:
        edge = tuple(edge)
        if len(edge) != 2:
            raise ValueError("Each edge must have two endpoints.")
        u, v = edge
        if u not in index or v not in index or u == v:
            raise ValueError("Edges must connect two distinct supplied vertices.")
        supplied_edges.append((u, v))
    supplied_edge_set = {frozenset(e) for e in supplied_edges}
    if len(supplied_edge_set) != len(supplied_edges):
        raise ValueError("Duplicate undirected edges are not supported.")

    is_city_grid = set(vertices) == set(CITY_COORDINATES_KM)
    construction = None
    if is_city_grid:
        derived_edges, construction = build_road_network(
            vertices, CITY_COORDINATES_KM, 3.5
        )
        if supplied_edge_set != {frozenset(e) for e in derived_edges}:
            raise ValueError(
                "Road edges must match the coordinate-derived 3x3 grid: "
                "12 horizontal/vertical links, no diagonal links."
            )
        edges = derived_edges
        assert construction["evaluated_pair_count"] == 36
        assert len(edges) == 12
    else:
        edges = supplied_edges

    graph = nx.Graph()
    graph.add_nodes_from(vertices)
    graph.add_edges_from(edges)
    m = graph.number_of_edges()
    degrees = np.array([graph.degree(v) for v in vertices], dtype=int)
    indexed_edges = [(index[u], index[v]) for u, v in edges]
    edge_indices = {tuple(sorted(e)) for e in indexed_edges}
    full_mask = (1 << n) - 1

    # The least significant bit is qubit 0, matching Aer count integers.
    states = np.arange(1 << n, dtype=np.uint64)
    populations = np.zeros(1 << n, dtype=np.int64)
    cuts = np.zeros(1 << n, dtype=np.int64)
    for i in range(n):
        populations += ((states >> i) & 1).astype(np.int64)
    for i, j in indexed_edges:
        cuts += (((states >> i) ^ (states >> j)) & 1).astype(np.int64)
    imbalances = n - 2 * populations
    energies = (
        lambda_cut * cuts.astype(float)
        + lambda_balance * imbalances.astype(float) ** 2
    )
    if not np.all(np.isfinite(energies)):
        raise ValueError("Objective weights overflow the numerical energy range.")

    def split_kind(region_a):
        if not is_city_grid:
            return "mixed"
        a = set(region_a)
        b = set(vertices) - a
        for axis, name in ((1, "row"), (0, "column")):
            levels = sorted({CITY_COORDINATES_KM[v][axis] for v in vertices})
            for level in levels[:-1]:
                side = {
                    v for v in vertices
                    if CITY_COORDINATES_KM[v][axis] <= level
                }
                if side == a or side == b:
                    return name
        return "mixed"

    candidates = {}
    # Even masks fix bit zero to zero; omit mask zero (the empty B region).
    for mask in range(2, 1 << n, 2):
        a = [v for i, v in enumerate(vertices) if not ((mask >> i) & 1)]
        b = [v for i, v in enumerate(vertices) if (mask >> i) & 1]
        cut = int(cuts[mask])
        volume_b = int(sum(degrees[i] for i in range(n) if (mask >> i) & 1))
        volume_a = 2 * m - volume_b
        modularity = (
            1.0 - cut / m
            - (volume_a / (2 * m)) ** 2
            - (volume_b / (2 * m)) ** 2
        ) if m else 0.0
        normalized_cut = (
            (cut / volume_a if volume_a else 0.0)
            + (cut / volume_b if volume_b else 0.0)
        )
        candidates[mask] = {
            "canonical_mask": mask,
            "partition": {"region_A": a, "region_B": b},
            "candidate_type": split_kind(a),
            "region_sizes": [len(a), len(b)],
            "region_volumes": [volume_a, volume_b],
            "size_imbalance": abs(len(a) - len(b)),
            "cut_size": cut,
            "weighted_objective": float(energies[mask]),
            "modularity_score": float(modularity),
            "normalized_cut_score": float(normalized_cut),
            "balance_constraint_score": float(1 - abs(len(a) - len(b)) / n),
        }

    candidate_list = list(candidates.values())
    exact_best = min(candidate_list, key=_candidate_key)
    exact_energy = exact_best["weighted_objective"]

    def is_optimal_energy(energy):
        return math.isclose(energy, exact_energy, rel_tol=1e-10, abs_tol=1e-10)

    exact_optima = [
        c for c in candidate_list if is_optimal_energy(c["weighted_objective"])
    ]
    minimum_imbalance = n % 2
    best_balanced = min(
        (c for c in candidate_list if c["size_imbalance"] == minimum_imbalance),
        key=_candidate_key,
    )

    class_summary = {}
    for name in ("row", "column", "mixed"):
        group = [c for c in candidate_list if c["candidate_type"] == name]
        class_summary[name] = {
            "count": len(group),
            "best_weighted_objective_partition": min(group, key=_candidate_key)
            if group else None,
        }

    # Pareto tradeoffs use the two actual objectives, not an implicit
    # preference for either the straight or mixed partition family.
    tradeoff_pairs = sorted({
        (c["cut_size"], c["size_imbalance"]) for c in candidate_list
    })
    pareto_pairs = [
        pair for pair in tradeoff_pairs
        if not any(
            other[0] <= pair[0] and other[1] <= pair[1] and other != pair
            for other in tradeoff_pairs
        )
    ]

    ref_mask = _reference_mask(known_reference_partition, vertices)
    reference_evaluation = (
        dict(candidates[ref_mask]) if ref_mask is not None else None
    )
    if reference_evaluation is not None:
        reference_evaluation["approximation_ratio"] = _minimization_ratio(
            reference_evaluation["weighted_objective"], exact_energy
        )

    classical_seconds = time.perf_counter() - started
    circuit_started = time.perf_counter()

    # x_i=(1-Z_i)/2 gives
    # H_C = lambda_cut*m/2 + lambda_balance*n
    #       + sum_{i<j}(2*lambda_balance-lambda_cut*A_ij/2) Z_i Z_j.
    # The constant is a global phase and is omitted from the circuit.
    # rzz(theta)=exp(-i*theta*ZZ/2), so theta=2*gamma*coefficient.
    gammas = ParameterVector("gamma", p_layers)
    betas = ParameterVector("beta", p_layers)
    circuit = QuantumCircuit(n, n)
    circuit.h(range(n))
    for layer in range(p_layers):
        for i, j in itertools.combinations(range(n), 2):
            coefficient = 2 * lambda_balance
            if (i, j) in edge_indices:
                coefficient -= lambda_cut / 2
            if coefficient != 0:
                circuit.rzz(2 * coefficient * gammas[layer], i, j)
        for i in range(n):
            circuit.rx(2 * betas[layer], i)
    circuit.measure(range(n), range(n))

    backend = AerSimulator(
        method="statevector",
        max_parallel_threads=1,
        max_parallel_experiments=1,
    )
    seed_children = np.random.SeedSequence(seed).spawn(n_repro_runs + 1)
    transpiler_seed = int(seed_children[0].generate_state(1)[0])
    compiled = transpile(
        circuit, backend, seed_transpiler=transpiler_seed, optimization_level=1
    )
    objective_scale = max(1.0, float(np.ptp(energies)))
    circuit_seconds = time.perf_counter() - circuit_started

    def get_counts(theta, shots, simulator_seed):
        assignments = {
            gammas[i]: float(theta[i]) for i in range(p_layers)
        }
        assignments.update({
            betas[i]: float(theta[p_layers + i]) for i in range(p_layers)
        })
        bound = compiled.assign_parameters(assignments, inplace=False, strict=False)
        result = backend.run(
            bound, shots=shots, seed_simulator=simulator_seed
        ).result()
        return {
            int(bitstring.replace(" ", ""), 2): int(count)
            for bitstring, count in result.get_counts().items()
        }

    runs = []
    optimization_seconds = 0.0
    sampling_seconds = 0.0
    refinement_seconds = 0.0

    for run_index, child in enumerate(seed_children[1:]):
        run_started = time.perf_counter()
        run_seed, opt_seed, final_seed = map(int, child.generate_state(3))
        rng = np.random.default_rng(run_seed)
        theta0 = np.concatenate([
            rng.uniform(0.05, math.pi / 2, p_layers),
            rng.uniform(-math.pi / 4, math.pi / 4, p_layers),
        ])
        cache = {}
        best_evaluated = {"value": math.inf, "theta": None}

        def objective(theta):
            key = tuple(float(x) for x in theta)
            if key not in cache:
                # Common random numbers make repeated parameter evaluations
                # deterministic while retaining finite-shot estimation.
                counts = get_counts(theta, opt_shots, opt_seed)
                estimate = sum(
                    float(energies[mask]) * count for mask, count in counts.items()
                ) / sum(counts.values())
                cache[key] = float(estimate)
            estimate = cache[key]
            if estimate < best_evaluated["value"]:
                best_evaluated["value"] = estimate
                best_evaluated["theta"] = np.asarray(theta, dtype=float).copy()
            return estimate / objective_scale

        stage_started = time.perf_counter()
        optimized = minimize(
            objective,
            theta0,
            method="COBYLA",
            options={"maxiter": maxiter, "rhobeg": 0.5, "tol": 1e-3},
        )
        # Retain the best actually evaluated point rather than trusting the
        # optimizer's last iterate on a finite-shot objective.
        theta = best_evaluated["theta"]
        optimization_elapsed = time.perf_counter() - stage_started
        optimization_seconds += optimization_elapsed

        stage_started = time.perf_counter()
        counts = get_counts(theta, final_shots, final_seed)
        sampling_elapsed = time.perf_counter() - stage_started
        sampling_seconds += sampling_elapsed
        total_counts = sum(counts.values())

        canonical_counts = {}
        for mask, count in counts.items():
            if mask not in (0, full_mask):
                canonical = _canonical_mask(mask, full_mask)
                canonical_counts[canonical] = canonical_counts.get(canonical, 0) + count
        valid_count = sum(canonical_counts.values())
        raw_mask = (
            min(canonical_counts, key=lambda mask: _candidate_key(candidates[mask]))
            if canonical_counts else None
        )

        # Empty regions are not valid administrative partitions. If every
        # final sample is empty/full, explicitly use a balanced classical
        # seed instead of pretending QAOA supplied a feasible solution.
        fallback = raw_mask is None
        start_mask = (
            raw_mask if raw_mask is not None
            else sum(1 << i for i in range(1, 1 + n // 2))
        )
        stage_started = time.perf_counter()
        refined_mask, refinement = _local_refine(start_mask, candidates, n)
        refinement_elapsed = time.perf_counter() - stage_started
        refinement_seconds += refinement_elapsed
        selected = candidates[refined_mask]

        count_digest = hashlib.sha256(
            json.dumps(sorted(counts.items()), separators=(",", ":")).encode()
        ).hexdigest()

        runs.append({
            "run_index": run_index,
            "initialization_seed": run_seed,
            "optimization_simulator_seed": opt_seed,
            "final_simulator_seed": final_seed,
            "optimizer": "COBYLA",
            "optimizer_success": bool(optimized.success),
            "optimizer_message": str(optimized.message),
            "optimizer_evaluations": int(optimized.nfev),
            "distinct_quantum_objective_evaluations": len(cache),
            "initial_parameters": theta0.tolist(),
            "optimized_parameters": {
                "gamma": theta[:p_layers].tolist(),
                "beta": theta[p_layers:].tolist(),
            },
            "optimization_estimated_energy": best_evaluated["value"],
            "final_sample_mean_energy": float(sum(
                float(energies[mask]) * count for mask, count in counts.items()
            ) / total_counts),
            "final_feasible_sample_fraction": valid_count / total_counts,
            "distinct_feasible_partitions_sampled": len(canonical_counts),
            "final_optimal_sample_fraction": sum(
                count for mask, count in canonical_counts.items()
                if is_optimal_energy(candidates[mask]["weighted_objective"])
            ) / total_counts,
            "best_quantum_sample": candidates[raw_mask] if raw_mask is not None else None,
            "best_quantum_sample_approximation_ratio": (
                _minimization_ratio(candidates[raw_mask]["weighted_objective"], exact_energy)
                if raw_mask is not None else None
            ),
            "classical_fallback_used": fallback,
            "local_refinement": refinement,
            "selected_partition_evaluation": selected,
            "approximation_ratio": _minimization_ratio(
                selected["weighted_objective"], exact_energy
            ),
            "reached_exact_weighted_optimum": is_optimal_energy(
                selected["weighted_objective"]
            ),
            "final_counts_sha256": count_digest,
            "optimization_seconds": optimization_elapsed,
            "final_sampling_seconds": sampling_elapsed,
            "local_refinement_seconds": refinement_elapsed,
            "runtime_seconds": time.perf_counter() - run_started,
        })

    winning_run = min(
        runs, key=lambda run: _candidate_key(run["selected_partition_evaluation"])
    )
    selected = winning_run["selected_partition_evaluation"]
    selected_mask = selected["canonical_mask"]
    selected_a = set(selected["partition"]["region_A"])
    cross_boundary_roads = [
        [u, v] for u, v in edges if (u in selected_a) != (v in selected_a)
    ]

    partition_frequencies = {}
    for run in runs:
        mask = run["selected_partition_evaluation"]["canonical_mask"]
        partition_frequencies[str(mask)] = partition_frequencies.get(str(mask), 0) + 1

    metric_statistics = {}
    for metric in (
        "weighted_objective", "cut_size", "modularity_score",
        "normalized_cut_score", "balance_constraint_score",
    ):
        values = [run["selected_partition_evaluation"][metric] for run in runs]
        metric_statistics[metric] = {
            "mean": float(np.mean(values)),
            "population_standard_deviation": float(np.std(values)),
        }

    result = {
        "modularity_score": selected["modularity_score"],
        "normalized_cut_score": selected["normalized_cut_score"],
        "balance_constraint_score": selected["balance_constraint_score"],
        "approximation_ratio": _minimization_ratio(
            selected["weighted_objective"], exact_energy
        ),
        "runtime": None,
        "reproducibility": {
            "base_seed": seed,
            "number_of_runs": n_repro_runs,
            "transpiler_seed": transpiler_seed,
            "backend": "qiskit_aer.AerSimulator",
            "simulation_method": "statevector with finite-shot sampling",
            "simulator_parallel_threads": 1,
            "package_versions": _package_versions(),
            "seed_policy": "SeedSequence children; separate initialization, optimization, and final sampling seeds",
            "repeatability_note": (
                "Same inputs, seed, package versions and platform are intended "
                "to replay results. These runs test different seeded starts, "
                "not repeated execution of one seed. Runtime is not deterministic."
            ),
            "same_seed_replay_test_performed": False,
            "partition_frequencies_by_canonical_mask": partition_frequencies,
            "selected_partition_frequency": (
                partition_frequencies[str(selected_mask)] / n_repro_runs
            ),
            "exact_optimum_success_fraction": sum(
                run["reached_exact_weighted_optimum"] for run in runs
            ) / n_repro_runs,
            "metric_statistics": metric_statistics,
            "runs": runs,
        },
        "partition": selected["partition"],
        "region_sizes": selected["region_sizes"],
        "cut_size": selected["cut_size"],
        "cross_boundary_roads": cross_boundary_roads,
        "weighted_objective": selected["weighted_objective"],
        "selected_run_index": winning_run["run_index"],
        "selection_method": (
            "Best finite-shot QAOA candidate in each run, followed by "
